/* ---------- kinds: the "кто на фото" level — species, not breeds ---------- */
const KIND_GROUPS=[
  ['cat','Кошка','кошка кот котик котенок котёнок',s=>s.type==='cat','cat_domestic'],
  ['dog','Собака','собака пес пёс щенок песик',s=>s.type==='dog','dog_mongrel'],
  ['hamster','Хомяк','хомяк хомячок',s=>/^hamster/.test(s.id),'hamster_syr'],
  ['guinea','Морская свинка','свинка морская',s=>/^guinea/.test(s.id),'guinea'],
  ['rabbit','Кролик','кролик крольчонок крол',s=>/^rabbit/.test(s.id),'rabbit'],
  ['horse','Лошадь','лошадь конь лошадка',s=>s.id==='horse'||s.id==='pony','horse'],
  ['goldfish','Золотая рыбка','',s=>s.id==='goldfish'||s.id==='telescope','goldfish'],
  ['turtle','Черепаха','черепаха черепашка',s=>s.type==='turtle','tortoise'],
  ['snake','Змея','змея змейка',s=>s.type==='snake','cornsnake'],
  ['croc','Крокодил','крокодил',s=>s.type==='croc','croc'],
  ['frog','Лягушка','лягушка лягуха',s=>s.id==='treefrog'||s.id==='hornedfrog','treefrog']
];
const KIND_SHORT={mouse:'Мышь',rat:'Крыса',roach:'Таракан',gecko:'Геккон',agama:'Агама',ant:'Муравьи',hedgehog:'Ёж',goat:'Коза',finch:'Амадина',minipig:'Мини-пиг',tarantula:'Паук-птицеед'};
const KINDS=[], kindOf={};
for(const s of SP){ const g=KIND_GROUPS.find(g=>g[3](s)), id=g?g[0]:s.id; let k=KINDS.find(k=>k.id===id);
  if(!k){ k={id,name:g?g[1]:(KIND_SHORT[s.id]||s.name),syn:g?g[2]:'',type:s.type,rep:g?g[4]:s.id,species:[]}; KINDS.push(k); }
  k.species.push(s.id); k.syn+=' '+s.name+' '+s.syn; kindOf[s.id]=id; }

/* ---------- photo colors → colorway (shared by the app and the package) ----------
   Each colorway is split into zones (base / light / pattern) with their pixel shares. The photo colors
   are assigned to the zones so that the shares match and the hues and light/dark order stay close. */
const _zoneCache={};
function presetZones(sp,i){ const key=sp.id+'#'+i; if(_zoneCache[key]) return _zoneCache[key];
  const p=sp.presets[i], cfg={spec:{rig:sp.rig,p:sp.p},pattern:p.pattern,colors:{base:p.base,sec:p.sec,pat:p.pat,eye:p.eye,ext:p.ext||'3e2731',feet:p.feet||'e4a672',acc:'e43b44'},neck:'none',head:'none',paint:{},paintBase:'constructor'};
  const S=buildSprite(cfg,'stand',0); let b=0,w=0,t=0;
  for(const x of S.slots){ if(x===SL.B||x===SL.BD||x===SL.BL) b++; else if(x===SL.W||x===SL.WD||x===SL.WL) w++; else if(x===SL.P||x===SL.PD||x===SL.PL) t++; }
  const n=(b+w+t)||1, sh={base:b/n,sec:w/n,pat:t/n}, zones=[];
  for(const r of ['base','sec','pat']){ if(sh[r]<=0) continue; const z=zones.find(z=>z.hex===p[r]); if(z){ z.share+=sh[r]; z.roles.push(r); } else zones.push({hex:p[r],share:sh[r],roles:[r]}); }
  return _zoneCache[key]={sh,zones};
}
function matchPreset(sp,i,photoColors){
  const p=sp.presets[i], {zones}=presetZones(sp,i);
  const cl=photoColors.filter(o=>o.share>=0.05).sort((a,b)=>b.share-a.share).slice(0,6), tot=cl.reduce((s,o)=>s+o.share,0);
  if(!cl.length) return null;
  const pc=cl.map(o=>({hex:o.hex,share:o.share/tot,rgb:hexRgb(o.hex)})), zr=zones.map(z=>hexRgb(z.hex)), K=pc.length, idx=zones.map(()=>0);
  let best=null;
  for(let n=0,all=Math.pow(K,zones.length);n<all;n++){
    let m=n; for(let z=0;z<zones.length;z++){ idx[z]=m%K; m=Math.floor(m/K); }
    const got=new Array(K).fill(0); let cd=0, ord=0, l1=0;
    for(let z=0;z<zones.length;z++){ got[idx[z]]+=zones[z].share; cd+=zones[z].share*Math.sqrt(cdist(zr[z],pc[idx[z]].rgb))/765; }
    for(let j=0;j<K;j++) l1+=Math.abs(pc[j].share-got[j]);
    for(let a=0;a<zones.length;a++) for(let b=a+1;b<zones.length;b++){ const da=lum(zr[a])-lum(zr[b]), dp=lum(pc[idx[a]].rgb)-lum(pc[idx[b]].rgb); if(Math.abs(da)>30&&da*dp<0) ord+=0.2; }
    const sc=l1+0.6*cd+ord; if(!best||sc<best.sc) best={sc,idx:idx.slice()};
  }
  const res={base:p.base,sec:p.sec,pat:p.pat,eye:p.eye,pattern:p.pattern};
  zones.forEach((z,k)=>z.roles.forEach(r=>{ res[r]=pc[best.idx[k]].hex; }));
  // a zone that merged into the coat keeps its contrast: a shade or a tint of the new base
  const L=h=>lum(hexRgb(h));
  for(const r of ['sec','pat']) if(res[r]===res.base&&p[r]!==p.base){
    res[r]=L(p[r])<L(p.base)-20?nearestPal(hexRgb(shadeOf(shadeOf(res.base)))):L(p[r])>L(p.base)+20?nearestPal(hexRgb(lightOf(lightOf(res.base)))):res.base; }
  return {res,score:best.sc};
}
